-- test-setup: database/tests/blueprint/fixtures.sql
-- test-setup: database/tests/helpers/payment_lifecycle_fixture.sql
DO $$
DECLARE f jsonb; req jsonb; r jsonb; oc bigint; org bigint; oid bigint; tid bigint; tid2 bigint;
 opt bigint; opt2 bigint; seat_ids bigint[]; prod bigint; pt bigint; pay bigint; ver bigint; scope_ver bigint; actor uuid; un bigint; x jsonb; table_node uuid:=gen_random_uuid();
BEGIN
 PERFORM set_config('festapp.email_wake','scheduled',true);
 f:=public.blueprint_test_fixture_internal();oc:=(f->>'occasion')::bigint;actor:=(f->>'actor')::uuid;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 SELECT organization,unit INTO org,un FROM public.occasions WHERE id=oc;
 INSERT INTO public.unit_users(unit,"user",is_editor,is_manager) VALUES(un,actor,true,true) ON CONFLICT DO NOTHING;
 INSERT INTO eshop.ticket_wallet_integrations(organization,issuer,environment,web_origin) VALUES(org,'1234','producers','https://queue.invalid');
 r:=public.update_blueprint_client_sync_v1(f->'request',gen_random_uuid());
 PERFORM assert_eq(r->>'status','applied','real blueprint setup');
 SELECT array_agg(spot ORDER BY spot) INTO seat_ids FROM eshop.blueprint_seat_bindings WHERE blueprint=(f->>'blueprint')::bigint;
 oid:=public.allocate_ticket_order_identity_internal((f->>'form')::bigint);
 INSERT INTO eshop.payment_info(amount,paid,currency_code) VALUES(200,200,'CZK') RETURNING id INTO pay;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','QUEUE-PRODUCER-1') RETURNING id INTO tid;
 INSERT INTO eshop.tickets(occasion,state,ticket_symbol) VALUES(oc,'paid','QUEUE-PRODUCER-2') RETURNING id INTO tid2;
 INSERT INTO eshop.order_product_ticket("order",ticket,product) VALUES(oid,tid,(f->>'product')::bigint) RETURNING id INTO opt;
 INSERT INTO eshop.order_product_ticket("order",ticket,product) VALUES(oid,tid2,(f->>'product')::bigint) RETURNING id INTO opt2;
 UPDATE eshop.orders SET state='paid',price=200,payment_info=pay,data=jsonb_build_object('email','fixture@queue.invalid','tickets',jsonb_build_array(
  jsonb_build_object('id',tid,'products',jsonb_build_array(public._swap_spots_generate_product_json((f->>'product')::bigint,seat_ids[1]))),
  jsonb_build_object('id',tid2,'products',jsonb_build_array(public._swap_spots_generate_product_json((f->>'product')::bigint,seat_ids[2]))))) WHERE id=oid;
 UPDATE eshop.spots SET order_product_ticket=CASE WHEN id=seat_ids[1] THEN opt ELSE opt2 END WHERE id=ANY(seat_ids[1:2]);
 INSERT INTO eshop.ticket_wallet_objects(ticket_id,organization,occasion,issuer,environment,object_id,class_id)
 SELECT t,org,oc,'1234','producers','1234.producer-'||t,'1234.producer-class-'||oc FROM unnest(ARRAY[tid,tid2]) t;
 PERFORM public.enqueue_ticket_wallet_internal(ARRAY[tid,tid2]);
 SELECT requested INTO ver FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid;
 -- Preview executes the actual swap but rolls its work queue changes back.
 r:=public.preview_blueprint_swap(seat_ids[1],seat_ids[2]);
 PERFORM assert_eq((r->>'code')::int,200,'real swap preview');
 PERFORM assert_eq((SELECT requested FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),ver,'preview does not enqueue');
 r:=public.swap_spot_tickets_client_sync_v1(seat_ids[1],seat_ids[2],gen_random_uuid());
 PERFORM assert_eq(r->>'status','applied','actual two-customer swap');
 PERFORM assert_true((SELECT bool_and(requested>ver) FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=ANY(ARRAY[tid,tid2])),'both swap sides enqueued');
 SELECT requested INTO ver FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid;
 -- Each independent mutation is rolled back after proving same-transaction work.
 BEGIN
  PERFORM public.scanner_admit_ticket_internal(tid);
  PERFORM public.update_ticket_to_unused_ws(tid);
  PERFORM assert_true((SELECT requested>=ver+2 FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'admit and unused enqueue');
  RAISE SQLSTATE 'P9999';
 EXCEPTION WHEN SQLSTATE 'P9999' THEN NULL; END;
 BEGIN
  UPDATE eshop.orders SET state='ordered' WHERE id=oid;
  UPDATE eshop.tickets SET state='ordered' WHERE id=ANY(ARRAY[tid,tid2]);
  r:=public.update_order_and_tickets_to_paid_ws(oid);
  PERFORM assert_eq((r->>'code')::int,200,'real paid command: '||r::text);
  PERFORM assert_true((SELECT requested>ver FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'paid enqueues');
  RAISE SQLSTATE 'P9999';
 EXCEPTION WHEN SQLSTATE 'P9999' THEN NULL; END;
 BEGIN
  UPDATE eshop.payment_info SET paid=0 WHERE id=pay;
  PERFORM public.reconcile_order_payment_internal_v1(oid,'refund_fact');
  PERFORM assert_true((SELECT requested>ver FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'refund reconciliation enqueues');
  RAISE SQLSTATE 'P9999';
 EXCEPTION WHEN SQLSTATE 'P9999' THEN NULL; END;
 BEGIN
  PERFORM public.internal_storno_tickets_221(ARRAY[tid,tid2]);
  PERFORM assert_true((SELECT bool_and(requested>ver) FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=ANY(ARRAY[tid,tid2])),'storno enqueues before links disappear');
  PERFORM public.delete_order_internal_v1(oid);
  PERFORM assert_true(NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=tid),'real delete command');
  PERFORM assert_true(EXISTS(SELECT 1 FROM eshop.ticket_wallet_objects WHERE ticket_id=tid),'deletion retains remote identity');
  PERFORM assert_true((SELECT requested>ver+1 FROM eshop.ticket_wallet_work WHERE kind='object' AND ticket_id=tid),'delete enqueues tombstone');
  RAISE SQLSTATE 'P9999';
 EXCEPTION WHEN SQLSTATE 'P9999' THEN NULL; END;
 SELECT requested INTO scope_ver FROM eshop.ticket_wallet_work WHERE kind='occasion' AND resource=oc::text;
 PERFORM public.update_product_internal_v1(jsonb_build_object('id',(f->>'product')::bigint,'title','New admission title'));
 PERFORM assert_true((SELECT requested>scope_ver FROM eshop.ticket_wallet_work WHERE kind='occasion' AND resource=oc::text),'product title scope');
 -- A layout-only save reaches the same bounded occasion producer.
 UPDATE eshop.blueprints SET layout=jsonb_set(layout,'{nodes}',layout->'nodes'||jsonb_build_array('{"kind":"table","label":"Old table","transform":{"x":400,"y":600,"rotation":23},"width":220,"height":80,"surface":{"type":"rect"},"style":{"label":{"fontFamilyId":"font-family:f7b3a0ebd5b869a2c40433fdc5c003472743d3587c9ff15275ee2eaea54a19c5","size":28}}}'::jsonb||jsonb_build_object('id',table_node))) WHERE id=(f->>'blueprint')::bigint;
 UPDATE eshop.blueprint_seat_bindings SET group_node=table_node WHERE spot=seat_ids[2];
 req:=jsonb_set(f->'request','{expected_layout_revision}','1');
 req:=jsonb_set(req,'{layout}',(SELECT jsonb_set(layout,'{nodes,4,label}','"Příliš široký název stolu"') FROM eshop.blueprints WHERE id=(f->>'blueprint')::bigint));
 req:=jsonb_set(req,'{seatChanges}','[]');
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 -- Reuse the real canonical whole-text fixture, without inventing glyph paths.
 PERFORM public.register_blueprint_text_resources(oc,NULL,'{"protocol":2,"fontFamilies":{"font-family:f7b3a0ebd5b869a2c40433fdc5c003472743d3587c9ff15275ee2eaea54a19c5":{"id":"font-family:f7b3a0ebd5b869a2c40433fdc5c003472743d3587c9ff15275ee2eaea54a19c5","hash":"f7b3a0ebd5b869a2c40433fdc5c003472743d3587c9ff15275ee2eaea54a19c5","faces":{"400:italic":"gf:cab2f63113328b72dce6b3e1eac7f268a27290911049f79fe760630c7befd861","400:normal":"gf:7f3ec5073a282c666c9a0063573345841229caf50ed34d33017e20d441bf5caf","700:italic":"gf:07b9b53ecf7da2d6c4af6841bb5c9e16087594914c6723a782805a4201b3cdc5","700:normal":"gf:a059c7343a09d6144d964625cb5d7cd9a0692772f981920c253941600447cb8d"},"family":"Roboto","version":1},"font-family:31472a6343eeef268a1c2e7368cb6ae0f9c6b0071f6b528c66e42a0187820028":{"id":"font-family:31472a6343eeef268a1c2e7368cb6ae0f9c6b0071f6b528c66e42a0187820028","hash":"31472a6343eeef268a1c2e7368cb6ae0f9c6b0071f6b528c66e42a0187820028","faces":{"400:italic":"gf:087dbc905b0464d41117744b9f63611c3741d4892e905d205e6fefe31c1cad50","400:normal":"gf:61e73c93b4892da99e134f6d51bb2fa003d74490589534835f2e6663eb123c95","700:italic":"gf:28deb67e11ba09b41ef4b2953a960a8e49603749c768661e38b77303349fb2a9","700:normal":"gf:5f28923bd89df53a46e4e4e2be7925df1ad8a0b0468bffff1ed160c982987284"},"family":"Amiri","version":1},"font-family:0e7143d0f98ab5f6f1ab81533ff3739cfa94e5b8f8b85675813ac406b3bf4e8a":{"id":"font-family:0e7143d0f98ab5f6f1ab81533ff3739cfa94e5b8f8b85675813ac406b3bf4e8a","hash":"0e7143d0f98ab5f6f1ab81533ff3739cfa94e5b8f8b85675813ac406b3bf4e8a","faces":{"400:italic":"gf:0504e39af7e5ed18179046973556aa791a247ba24f0851a26da501144dcaf4f0","400:normal":"gf:79f9b78b96c3d89b3f45803facad00dc5cf7a958e433f03aa0b2dc34dfa1846d"},"family":"Tiro Devanagari Hindi","version":1}},"textLayouts":{"layout-text:567a952ecb16629308724a9d3ff97179e83209169a13110b7f4bbee9c1b38a49":{"id":"layout-text:567a952ecb16629308724a9d3ff97179e83209169a13110b7f4bbee9c1b38a49","descriptor":{"layoutResourceProtocol":2,"policy":